package com.vibecode.roadmap.application;
import static org.assertj.core.api.Assertions.assertThat;
import com.vibecode.output.domain.EvidenceType; import com.vibecode.project.application.ProjectService; import com.vibecode.prompt.application.DeterministicPromptBuilder; import com.vibecode.prompt.domain.PromptType; import com.vibecode.roadmap.domain.RoadmapPhaseRecord; import com.vibecode.task.domain.RiskLevel; import com.vibecode.task.domain.WorkflowTask; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest;
@SpringBootTest class WorkflowEndToEndTest { @Autowired ProjectService projects; @Autowired WorkflowService flow; @Autowired DeterministicNextStepEngine next; @Autowired DeterministicPromptBuilder prompts;
 @Test void barberFlowMovesFromEvidenceToNextStepAndCorrectionPrompt(){var p=projects.create("BarberFlow","", "Booking for barbers");flow.createRoadmap(p.getId());RoadmapPhaseRecord setup=flow.addPhase(p.getId(),1,"Setup","");RoadmapPhaseRecord auth=flow.addPhase(p.getId(),2,"Authentication","");flow.addPhase(p.getId(),3,"Dashboard","");WorkflowTask user=flow.addTask(p.getId(),auth.id(),1,"Create User","Create user entity",RiskLevel.MEDIUM);WorkflowTask security=flow.addTask(p.getId(),auth.id(),2,"Configure Spring Security","Configure security",RiskLevel.HIGH);flow.dependency(p.getId(),security.id(),user.id());flow.criterion(p.getId(),user.id(),"Build passes",true);flow.criterion(p.getId(),security.id(),"Security build passes",true);flow.addEvidence(p.getId(),user.id(),EvidenceType.BUILD_RESULT,"BUILD SUCCESS\nTests run: 18, Failures: 0, Errors: 0","maven");assertThat(next.recommend(p.getId()).taskId()).isEqualTo(security.id());flow.addEvidence(p.getId(),security.id(),EvidenceType.BUILD_RESULT,"BUILD FAILURE\nCompilation error in SecurityConfig","maven");assertThat(next.recommend(p.getId()).type()).isEqualTo(NextStepType.FIX_ERROR);assertThat(prompts.generate(p.getId(),security.id(),PromptType.FIX_ERROR).content()).contains("Compilation error in SecurityConfig");flow.addEvidence(p.getId(),security.id(),EvidenceType.BUILD_RESULT,"BUILD SUCCESS\nTests run: 18, Failures: 0, Errors: 0","maven");assertThat(next.recommend(p.getId()).type()).isNotEqualTo(NextStepType.FIX_ERROR);}}
